import React, { useState } from 'react';
import Categories from './components/pages/Categories';
import BankAccounts from './components/pages/BankAccounts';
import Transactions from './components/pages/Transactions';
import Reports from './components/pages/Reports';
import Documents from './components/pages/Documents';
import Funcionamento from './components/pages/Funcionamento';
import CommentsReport from './components/pages/CommentsReport';
import Console from './components/ui/Console';
import AIChat from './components/ai/AIChat';
import { useAppData } from './hooks/useAppData';
import { Menu, X, Landmark, List, CreditCard, LayoutDashboard, Wallet, HeartPulse, Loader2, FileText, Activity, MessageSquare, ShieldCheck } from 'lucide-react';

type Page = 'Dashboard' | 'Conta Bancária' | 'Categorias' | 'Conta Corrente' | 'Cartão de Crédito' | 'Documentos' | 'Funcionamento' | 'Comentários';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<Page>('Dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const { isLoading: isDataLoading } = useAppData();

  if (isDataLoading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-900">
        <div className="text-center">
          <Loader2 className="w-16 h-16 text-[#c5a059] animate-spin mx-auto" />
          <p className="mt-6 text-xl font-light text-slate-300 tracking-widest">AUTENTICANDO...</p>
        </div>
      </div>
    );
  }

  const renderPage = () => {
    switch (activePage) {
      case 'Categorias':
        return <Categories />;
      case 'Conta Bancária':
        return <BankAccounts />;
      case 'Conta Corrente':
        return <Transactions transactionType="checking_account" title="Conta Corrente" />;
      case 'Cartão de Crédito':
        return <Transactions transactionType="credit_card" title="Cartão de Crédito" />;
      case 'Dashboard':
        return <Reports />;
      case 'Documentos':
        return <Documents />;
      case 'Funcionamento':
        return <Funcionamento />;
      case 'Comentários':
        return <CommentsReport />;
      default:
        return <Reports />;
    }
  };

  const menuItems: { name: Page; icon: React.ReactNode }[] = [
    { name: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
    { name: 'Conta Corrente', icon: <Wallet className="w-5 h-5" /> },
    { name: 'Cartão de Crédito', icon: <CreditCard className="w-5 h-5" /> },
    { name: 'Comentários', icon: <MessageSquare className="w-5 h-5" /> },
    { name: 'Documentos', icon: <FileText className="w-5 h-5" /> },
    { name: 'Conta Bancária', icon: <Landmark className="w-5 h-5" /> },
    { name: 'Categorias', icon: <List className="w-5 h-5" /> },
    { name: 'Funcionamento', icon: <Activity className="w-5 h-5" /> },
  ];

  const NavLink: React.FC<{ page: Page, icon: React.ReactNode }> = ({ page, icon }) => (
    <li key={page}>
      <a
        href="#"
        onClick={(e) => {
          e.preventDefault();
          setActivePage(page);
          setIsSidebarOpen(false);
        }}
        className={`flex items-center gap-3 p-3.5 rounded-xl transition-all duration-300 font-medium ${
          activePage === page
            ? 'sidebar-item-active text-white scale-[1.02]'
            : 'text-slate-400 hover:bg-slate-800 hover:text-white'
        }`}
      >
        <span className={activePage === page ? 'text-white' : 'text-[#c5a059]'}>
          {icon}
        </span>
        <span className="tracking-wide">{page}</span>
      </a>
    </li>
  );

  return (
    <div className="flex h-screen bg-slate-50">
      {/* Sidebar */}
      <aside
        className={`bg-slate-900 w-72 min-h-screen p-6 flex flex-col transition-transform duration-500 ease-in-out fixed lg:relative lg:translate-x-0 z-30 shadow-2xl ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        <div className="flex items-center gap-4 pb-8 mb-4 border-b border-slate-800">
          <div className="bg-gradient-to-br from-[#c5a059] to-[#d9b36a] p-2.5 rounded-xl shadow-lg">
            <ShieldCheck className="w-7 h-7 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">Curatela</h1>
            <p className="text-[10px] text-[#c5a059] font-bold uppercase tracking-[0.2em]">Sovereign Accounts</p>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto no-scrollbar">
          <ul className="space-y-1.5">
            {menuItems.map(item => <NavLink key={item.name} page={item.name} icon={item.icon} />)}
          </ul>
        </nav>

        <div className="border-t border-slate-800 pt-6 mt-6">
            <div className="bg-slate-800/50 p-4 rounded-2xl border border-slate-700/50">
                <p className="text-[10px] text-[#c5a059] font-bold uppercase tracking-widest text-center">Proteção Garantida</p>
            </div>
            <p className="text-center text-[10px] text-slate-500 mt-4 font-medium uppercase tracking-widest">Versão Premium 2.5</p>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden relative">
        <header className="bg-white/80 backdrop-blur-xl border-b border-slate-200 p-4 flex items-center justify-between lg:hidden sticky top-0 z-20">
          <div className="flex items-center gap-3">
            <div className="bg-slate-900 p-2 rounded-lg">
              <ShieldCheck className="w-5 h-5 text-[#c5a059]" />
            </div>
            <h1 className="text-lg font-bold text-slate-900 tracking-tight">Curatela Contas</h1>
          </div>
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 text-slate-600">
            {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 sm:p-8 lg:p-10 bg-slate-50">
          <div className="max-w-7xl mx-auto animate-slide-up">
            {renderPage()}
          </div>
        </main>
      </div>

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-20 lg:hidden transition-opacity duration-500" 
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}

      {/* Modals & Global Components */}
      <Console />
      <AIChat />
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { useAppData } from '../../hooks/useAppData';
import { formatCurrency } from '../../utils/formatters';
import { CategoryType } from '../../types';
import { ArrowUpRight, ArrowDownLeft, Scale, ShieldCheck, Landmark } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';

const CustomLegend = (props: any) => {
  const { payload } = props;
  if (!payload || !payload.length) {
    return null;
  }

  return (
    <div className="mt-6 w-full">
        <ul className="grid grid-cols-2 md:grid-cols-3 gap-x-6 gap-y-2.5 text-xs font-semibold justify-center">
        {payload.map((entry: any, index: number) => (
            <li
            key={`item-${index}`}
            className="flex items-center gap-2.5"
            title={entry.value}
            >
            <span
                className="w-3 h-3 rounded-full inline-block flex-shrink-0 shadow-sm"
                style={{ backgroundColor: entry.color }}
            />
            <span className="text-slate-500 truncate uppercase tracking-wider">
                {entry.value}
            </span>
            </li>
        ))}
        </ul>
    </div>
  );
};


const Reports: React.FC = () => {
  const { accounts, transactions, categories, calculateCurrentBalance } = useAppData();

  const totalBalance = useMemo(() => {
    return accounts.reduce((sum, acc) => sum + calculateCurrentBalance(acc.id), 0);
  }, [accounts, calculateCurrentBalance]);

  const monthlySummary = useMemo(() => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);

    const monthTransactions = transactions.filter(t => {
      const tDate = new Date(t.date);
      tDate.setUTCHours(0,0,0,0);
      return tDate >= firstDay && tDate <= lastDay;
    });

    const income = monthTransactions
      .filter(t => t.nature === 'RECEITA')
      .reduce((sum, t) => sum + t.value, 0);

    const expense = monthTransactions
      .filter(t => t.nature === 'DESPESA')
      .reduce((sum, t) => sum + t.value, 0);

    return { income, expense };
  }, [transactions]);

  const expenseByCategoryData = useMemo(() => {
    const expenseData: { [key: string]: number } = {};

    transactions
        .filter(t => t.nature === 'DESPESA')
        .forEach(t => {
            const categoryName = categories.find(c => c.id === t.categoryId)?.name || 'Outros';
            if(expenseData[categoryName]) {
                expenseData[categoryName] += t.value;
            } else {
                expenseData[categoryName] = t.value;
            }
        });

    return Object.entries(expenseData).map(([name, value]) => ({ name, value })).sort((a,b) => b.value - a.value);

  }, [transactions, categories]);

  const COLORS = ['#0f172a', '#c5a059', '#334155', '#d9b36a', '#475569', '#94a3b8', '#cbd5e1'];

  return (
    <div className="space-y-10">
      <div>
        <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">Dashboard Executivo</h1>
        <p className="text-slate-500 mt-2 font-medium tracking-wide">Relatório consolidado de ativos e fluxos financeiros.</p>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
        <div className="bg-slate-900 text-white p-8 rounded-3xl shadow-2xl flex flex-col justify-between relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform duration-500">
                <ShieldCheck size={120} />
            </div>
            <div className="relative z-10">
                <p className="font-bold text-[#c5a059] uppercase tracking-[0.2em] text-[10px]">Patrimônio Total</p>
                <p className="text-4xl font-black mt-3 tracking-tighter">{formatCurrency(totalBalance)}</p>
            </div>
            <div className="flex items-center gap-2 mt-6 font-semibold text-xs text-slate-400 tracking-wider relative z-10">
                <Landmark size={14} className="text-[#c5a059]" />
                <span>Consolidado Interbancário</span>
            </div>
        </div>

        <div className="bg-white p-8 rounded-3xl premium-shadow border border-slate-100 card-hover">
            <div className="flex items-center justify-between">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Receitas do Mês</p>
                <div className="bg-emerald-50 text-emerald-600 p-2.5 rounded-2xl">
                    <ArrowUpRight size={20} />
                </div>
            </div>
            <p className="text-3xl font-black text-slate-900 mt-3">{formatCurrency(monthlySummary.income)}</p>
        </div>

        <div className="bg-white p-8 rounded-3xl premium-shadow border border-slate-100 card-hover">
            <div className="flex items-center justify-between">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Despesas do Mês</p>
                <div className="bg-rose-50 text-rose-600 p-2.5 rounded-2xl">
                    <ArrowDownLeft size={20} />
                </div>
            </div>
            <p className="text-3xl font-black text-slate-900 mt-3">{formatCurrency(monthlySummary.expense)}</p>
        </div>

        <div className="bg-white p-8 rounded-3xl premium-shadow border border-slate-100 card-hover">
            <div className="flex items-center justify-between">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Balanço Líquido</p>
                 <div className="bg-slate-50 text-slate-600 p-2.5 rounded-2xl">
                    <Scale size={20} />
                </div>
            </div>
            <p className={`text-3xl font-black mt-3 ${monthlySummary.income - monthlySummary.expense >= 0 ? 'text-slate-900' : 'text-rose-600'}`}>
                {formatCurrency(monthlySummary.income - monthlySummary.expense)}
            </p>
        </div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-3xl premium-shadow border border-slate-100">
           <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-8">Alocação por Categoria</h2>
            {expenseByCategoryData.length > 0 ? (
                <div style={{ width: '100%', height: 480 }}>
                    <ResponsiveContainer>
                        <PieChart>
                            <Pie 
                                data={expenseByCategoryData} 
                                dataKey="value" 
                                nameKey="name" 
                                cx="50%" 
                                cy="40%" 
                                innerRadius={90} 
                                outerRadius={120} 
                                paddingAngle={5}
                                fill="#8884d8" 
                                labelLine={false} 
                                stroke="none"
                            >
                                {expenseByCategoryData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                            </Pie>
                            <Tooltip 
                                formatter={(value: number) => formatCurrency(value)} 
                                contentStyle={{ backgroundColor: '#ffffff', border: 'none', borderRadius: '1.5rem', boxShadow: '0 10px 30px -5px rgba(0,0,0,0.1)' }} 
                            />
                            <Legend content={<CustomLegend />} />
                        </PieChart>
                    </ResponsiveContainer>
                </div>
            ) : <p className="text-slate-400 text-center pt-24 font-medium italic">Dados insuficientes para visualização.</p>}
        </div>
        <div className="lg:col-span-3 bg-white p-8 rounded-3xl premium-shadow border border-slate-100">
          <h2 className="text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-8">Análise de Fluxo Mensal</h2>
          <div style={{ width: '100%', height: 320 }}>
             <ResponsiveContainer>
                <BarChart data={[{ name: 'Competência Atual', receitas: monthlySummary.income, despesas: monthlySummary.expense }]} margin={{ top: 20, right: 30, left: 10, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12, fontWeight: 600}} />
                    <YAxis tickFormatter={(value) => formatCurrency(Number(value))} axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} />
                    <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ backgroundColor: '#ffffff', border: 'none', borderRadius: '1.5rem', boxShadow: '0 10px 30px -5px rgba(0,0,0,0.1)' }} />
                    <Legend iconType="circle" wrapperStyle={{paddingTop: '20px'}} />
                    <Bar dataKey="receitas" fill="#c5a059" name="Créditos" radius={[8, 8, 0, 0]} barSize={60} />
                    <Bar dataKey="despesas" fill="#0f172a" name="Débitos" radius={[8, 8, 0, 0]} barSize={60} />
                </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { ReactNode } from 'react';
import { X } from 'lucide-react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: ReactNode;
}

const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 bg-slate-900/60 backdrop-blur-md flex justify-center items-center z-50 p-4 transition-all duration-500"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-[2.5rem] premium-shadow w-full max-w-lg m-4 animate-scale-in flex flex-col max-h-[92vh] border border-slate-100 overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex-shrink-0 flex justify-between items-center p-8 border-b border-slate-50 bg-slate-50/30">
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight">{title}</h2>
            <div className="h-1 w-12 bg-[#c5a059] mt-2 rounded-full"></div>
          </div>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-slate-900 transition-all p-2 rounded-full hover:bg-white shadow-sm border border-transparent hover:border-slate-100"
          >
            <X size={24} />
          </button>
        </div>
        <div className="p-8 overflow-y-auto no-scrollbar">
          {children}
        </div>
      </div>
    </div>
  );
};

export default Modal;

import React, { useState } from 'react';
import { useAppData } from '../../hooks/useAppData';
import { BankAccount, AccountType, TransactionNature, CategoryType } from '../../types';
import Modal from '../ui/Modal';
import CurrencyInput from '../ui/CurrencyInput';
import { formatCurrency } from '../../utils/formatters';
import { Plus, Edit, Trash2, Landmark, ShieldCheck } from 'lucide-react';

const BankAccountForm: React.FC<{
  onSubmit: (account: Omit<BankAccount, 'id'>) => Promise<void>;
  onClose: () => void;
  accountToEdit?: BankAccount | null;
}> = ({ onSubmit, onClose, accountToEdit }) => {
  const [name, setName] = useState(accountToEdit?.name || '');
  const [type, setType] = useState<AccountType>(accountToEdit?.type || AccountType.CONTA_CORRENTE);
  const [initialBalance, setInitialBalance] = useState(accountToEdit?.initialBalance || 0);
  const [dataAbertura, setDataAbertura] = useState(accountToEdit?.dataAbertura || new Date().toISOString().split('T')[0]);
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) {
      setError('O nome da conta é obrigatório.');
      return;
    }
    if (!dataAbertura) {
      setError('A data de abertura é obrigatória.');
      return;
    }
    setIsSubmitting(true);
    await onSubmit({ name, type, initialBalance, dataAbertura });
    setIsSubmitting(false);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div>
        <label htmlFor="accountName" className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5">Identificação da Conta</label>
        <input
          id="accountName"
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] focus:border-transparent transition-all gold-focus"
          placeholder="Ex: Conta Prime"
        />
        {error && !name.trim() && <p className="text-[10px] font-bold text-rose-500 mt-1 uppercase">{error}</p>}
      </div>
       <div>
        <label htmlFor="accountType" className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5">Tipo de Ativo</label>
        <select
          id="accountType"
          value={type}
          onChange={(e) => setType(e.target.value as AccountType)}
          className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] transition-all gold-focus"
        >
          <option value={AccountType.CONTA_CORRENTE}>Conta Corrente de Movimentação</option>
          <option value={AccountType.CONTA_POUPANCA}>Conta de Reserva Poupada</option>
        </select>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
        <div>
          <label htmlFor="dataAbertura" className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5">Início do Controle</label>
          <input
            type="date"
            id="dataAbertura"
            value={dataAbertura}
            onChange={(e) => setDataAbertura(e.target.value)}
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] gold-focus"
          />
        </div>
        <div>
          <label htmlFor="initialBalance" className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-1.5">Saldo de Abertura</label>
          <CurrencyInput value={initialBalance} onChange={setInitialBalance} id="initialBalance"/>
        </div>
      </div>

      <div className="bg-amber-50/50 p-4 rounded-2xl border border-amber-100">
        <p className="text-[10px] text-amber-700 font-bold uppercase tracking-wider text-center">Nota: O saldo inicial gerará um lançamento de ajuste automático.</p>
      </div>

      <div className="flex justify-end gap-3 pt-6">
        <button type="button" onClick={onClose} className="px-6 py-3 bg-white text-slate-600 border border-slate-200 rounded-2xl hover:bg-slate-50 font-bold transition-all">Cancelar</button>
        <button type="submit" disabled={isSubmitting} className="btn-premium-gold px-8 py-3 text-white rounded-2xl font-bold shadow-lg disabled:opacity-50">
          {isSubmitting ? 'SALVANDO...' : 'CONFIRMAR'}
        </button>
      </div>
    </form>
  );
};

const BankAccounts: React.FC = () => {
  const { accounts, addAccount, updateAccount, deleteAccount, calculateCurrentBalance, addTransaction, categories } = useAppData();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [accountToEdit, setAccountToEdit] = useState<BankAccount | null>(null);

  const handleOpenModal = (account?: BankAccount) => {
    setAccountToEdit(account || null);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setAccountToEdit(null);
  };

  const handleSubmit = async (data: Omit<BankAccount, 'id'>) => {
    if (accountToEdit) {
      await updateAccount({ ...accountToEdit, ...data });
    } else {
      const newAccount = await addAccount(data);

      if (newAccount && data.initialBalance > 0) {
          const receitaCategory = categories.find(c => c.type === CategoryType.RECEITA);
          if (!receitaCategory) {
              alert('Lançamento inicial falhou: Crie uma categoria de Receita primeiro.');
              handleCloseModal();
              return;
          }
          await addTransaction({
              description: 'Saldo Inicial (Ajuste)',
              nature: TransactionNature.RECEITA,
              accountId: newAccount.id,
              categoryId: receitaCategory.id,
              date: data.dataAbertura,
              value: data.initialBalance,
              type: 'checking_account'
          });
      }
    }
    handleCloseModal();
  };

  const handleDelete = async (id: string) => {
    if(window.confirm('Excluir esta conta removerá permanentemente todo o histórico associado. Deseja prosseguir?')) {
      await deleteAccount(id);
    }
  }

  return (
    <div className="space-y-10">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight">Custódia Bancária</h1>
          <p className="text-slate-500 mt-2 font-medium tracking-wide">Gerenciamento de ativos financeiros sob curatela.</p>
        </div>
        <button
          onClick={() => handleOpenModal()}
          className="btn-premium-navy flex items-center justify-center gap-2 px-8 py-4 text-white rounded-2xl font-bold shadow-2xl w-full sm:w-auto tracking-wide"
        >
          <Plus size={20} className="text-[#c5a059]" />
          ADICIONAR CONTA
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {accounts.length === 0 ? (
