                    <button type="button" onClick={() => { setNature(TransactionNature.RECEITA); setCategoryId(''); setPaymentMethod(undefined); }} className={`p-4 rounded-2xl font-bold uppercase tracking-widest text-[11px] transition-all ${nature === TransactionNature.RECEITA ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-200' : 'bg-slate-100 text-slate-500 hover:bg-emerald-50'}`}>Receita</button>
                    <button type="button" onClick={() => { setNature(TransactionNature.DESPESA); setCategoryId(''); }} className={`p-4 rounded-2xl font-bold uppercase tracking-widest text-[11px] transition-all ${nature === TransactionNature.DESPESA ? 'bg-rose-500 text-white shadow-lg shadow-rose-200' : 'bg-slate-100 text-slate-500 hover:bg-rose-50'}`}>Despesa</button>
                </div>
