const AddDocumentModal: React.FC<{
  isOpen: boolean;
  onClose: () => void;
}> = ({ isOpen, onClose }) => {
  const { addDocument } = useAppData();
  const [title, setTitle] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [scannedImage, setScannedImage] = useState<string | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const resetForm = () => {
    setTitle('');
    setFile(null);
    setScannedImage(null);
    setPreviewUrl(null);
    setError('');
    setIsSubmitting(false);
  }

  const handleClose = () => {
    resetForm();
    onClose();
  }

  const handleFileChange = (selectedFile: File) => {
    if (selectedFile) {
      setFile(selectedFile);
      setScannedImage(null);
      setPreviewUrl(URL.createObjectURL(selectedFile));
    }
  };

  const handleScanComplete = (base64Image: string) => {
    setScannedImage(base64Image);
    setFile(null);
    setPreviewUrl(`data:image/jpeg;base64,${base64Image}`);
    setIsScannerOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      setError('O título é obrigatório.');
      return;
    }
    if (!file && !scannedImage) {
      setError('Anexe ou digitalize um arquivo.');
      return;
    }

    setIsSubmitting(true);
    try {
        if (scannedImage) {
            await addDocument(title, `${title.replace(/\s+/g, '_')}.jpg`, scannedImage);
        } else if (file) {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onloadend = async () => {
                const base64String = (reader.result as string).split(',')[1];
                await addDocument(title, file.name, base64String);
            };
        }
        handleClose();
    } catch (err) {
        setError('Erro ao salvar documento.');
    } finally {
        setIsSubmitting(false);
    }
  }

  return (
    <>
      <Modal isOpen={isOpen} onClose={handleClose} title="Novo Documento">
        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label htmlFor="doc-title" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Identificação do Arquivo</label>
            <input 
              type="text"
              id="doc-title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] gold-focus font-medium"
              placeholder="Ex: Laudo Médico"
            />
          </div>

          <div className="border-2 border-dashed border-slate-200 rounded-[2rem] p-8 text-center bg-slate-50/50">
             {previewUrl ? (
                <img src={previewUrl} alt="Preview" className="max-h-48 mx-auto rounded-xl shadow-lg mb-6" />
             ) : (
                <UploadCloud className="mx-auto h-12 w-12 text-slate-300 mb-4" />
             )}
             <div className="flex flex-col gap-3">
                 <label htmlFor="file-upload" className="cursor-pointer text-xs font-extrabold text-[#c5a059] hover:text-[#d9b36a] uppercase tracking-widest transition-colors">
                    SELECIONAR DA GALERIA
                 </label>
                 <input id="file-upload" type="file" accept="image/*" className="hidden" onChange={(e) => e.target.files && handleFileChange(e.target.files[0])} />
                 <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">OU</span>
                 <button type="button" onClick={() => setIsScannerOpen(true)} className="text-xs font-extrabold text-slate-900 hover:text-slate-600 uppercase tracking-widest transition-colors">
                    DIGITALIZAR COM IA
                 </button>
             </div>
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-slate-50">
            <button type="button" onClick={handleClose} className="px-6 py-3 bg-white text-slate-600 border border-slate-200 rounded-2xl font-bold uppercase tracking-widest text-[10px]">Cancelar</button>
            <button type="submit" disabled={isSubmitting} className="btn-premium-gold px-8 py-3 text-white rounded-2xl font-extrabold uppercase tracking-widest text-[10px] shadow-lg disabled:opacity-50">
              {isSubmitting ? 'SALVANDO...' : 'CONFIRMAR'}
            </button>
          </div>
        </form>
      </Modal>
      <DocumentScannerModal isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScanComplete={handleScanComplete} />
    </>
  );
};

