            setNature(transactionToEdit.nature || TransactionNature.DESPESA);
            setDescription(transactionToEdit.description || '');
            setAccountId(transactionToEdit.accountId || '');
            setCategoryId(transactionToEdit.categoryId || '');
            setDate(transactionToEdit.date ? transactionToEdit.date.split('T')[0] : new Date().toISOString().split('T')[0]);
            setValue(transactionToEdit.value || 0);
            setComments(transactionToEdit.comments || '');
            setNumeroNota(transactionToEdit.numeroNota || '');
            setPaymentMethod(transactionToEdit.paymentMethod);
            setExistingAttachments(transactionToEdit.attachments || []);
        }
    }, [transactionToEdit]);

    const filteredCategories = useMemo(() => {
        return categories.filter(c => c.type === (nature as unknown as CategoryType));
    }, [categories, nature]);

    const validate = () => {
        const newErrors: { [key: string]: string } = {};
        if (!accountId) newErrors.accountId = 'Selecione uma conta.';
        if (!categoryId) newErrors.categoryId = 'Selecione uma categoria.';
        if (value <= 0) newErrors.value = 'O valor deve ser maior que zero.';
        if (!date) newErrors.date = 'A data é obrigatória.';

        if (nature === TransactionNature.DESPESA && transactionType === 'checking_account' && !paymentMethod) {
            newErrors.paymentMethod = 'Selecione o meio de pagamento.';
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validate()) return;
        setIsSubmitting(true);
        const transactionData = { 
            description, 
            nature, 
            accountId, 
            categoryId, 
            date, 
            value, 
            type: transactionType,
            comments,
            numeroNota,
            paymentMethod: (nature === TransactionNature.DESPESA && transactionType === 'checking_account') ? paymentMethod : undefined,
            attachments: existingAttachments
        };
        await onSubmit(transactionData, newAttachment ? [newAttachment] : []);
        setIsSubmitting(false);
    };

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        try {
            const { data } = await fileToBase64(file);
            setNewAttachment({
                id: crypto.randomUUID(),
                name: file.name,
                type: 'image_base64_jpeg',
                data: data
            });
        } catch (err) {
            console.error("Erro ao processar imagem:", err);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <div>
                <label className="block text-xs font-extrabold text-slate-400 uppercase tracking-[0.2em] mb-3">Natureza do Lançamento</label>
                <div className="grid grid-cols-2 gap-4">
                    <button type="button" onClick={() => { setNature(TransactionNature.RECEITA); setCategoryId(''); setPaymentMethod(undefined); }} className={`p-4 rounded-2xl font-bold uppercase tracking-widest text-[11px] transition-all ${nature === TransactionNature.RECEITA ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-200' : 'bg-slate-100 text-slate-500 hover:bg-emerald-50'}`}>Receita</button>
                    <button type="button" onClick={() => { setNature(TransactionNature.DESPESA); setCategoryId(''); }} className={`p-4 rounded-2xl font-bold uppercase tracking-widest text-[11px] transition-all ${nature === TransactionNature.DESPESA ? 'bg-rose-500 text-white shadow-lg shadow-rose-200' : 'bg-slate-100 text-slate-500 hover:bg-rose-50'}`}>Despesa</button>
                </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div>
                    <label htmlFor="description" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Descrição</label>
                    <input
                        type="text"
                        id="description"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] gold-focus font-medium"
                        placeholder="Ex: Uber, Supermercado..."
                    />
                </div>
                <div>
                    <label htmlFor="value" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Valor</label>
                    <CurrencyInput id="value" value={value} onChange={setValue} />
                    {errors.value && <p className="text-[10px] font-bold text-rose-500 mt-1 uppercase">{errors.value}</p>}
                </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div>
                    <label htmlFor="accountId" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Conta Bancária</label>
                    <select id="accountId" value={accountId} onChange={(e) => setAccountId(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] gold-focus font-semibold">
                        <option value="">Selecione...</option>
                        {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>
                </div>
                <div>
                    <label htmlFor="categoryId" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Categoria</label>
                    <select id="categoryId" value={categoryId} onChange={(e) => setCategoryId(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] gold-focus font-semibold">
                        <option value="">Selecione...</option>
                        {filteredCategories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                    </select>
                </div>
            </div>

            {nature === TransactionNature.DESPESA && transactionType === 'checking_account' && (
                <div>
                    <label htmlFor="paymentMethod" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Meio de Pagamento</label>
                    <select id="paymentMethod" value={paymentMethod || ''} onChange={(e) => setPaymentMethod(e.target.value as any)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] gold-focus font-semibold">
                        <option value="">Selecione...</option>
                        <option value="PIX">PIX</option>
                        <option value="Cartão de Débito">Cartão de Débito</option>
                        <option value="BOLETO">BOLETO</option>
                    </select>
                </div>
            )}

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div>
                    <label htmlFor="date" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Data</label>
                    <input
                        type={isDateInputFocused ? 'date' : 'text'}
                        id="date"
                        value={isDateInputFocused ? date : (date ? formatDate(date) : '')}
                        onFocus={() => setIsDateInputFocused(true)}
                        onBlur={() => setIsDateInputFocused(false)}
                        onChange={(e) => setDate(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] gold-focus font-medium tabular-nums"
                    />
                </div>
                <div>
                    <label htmlFor="numeroNota" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Número da Nota</label>
                    <input
                        type="text"
                        id="numeroNota"
                        value={numeroNota}
                        onChange={(e) => setNumeroNota(e.target.value)}
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-[#c5a059] gold-focus font-medium"
                        placeholder="Nº da Nota Fiscal"
                    />
                </div>
            </div>

            <div>
                <label htmlFor="comments" className="block text-xs font-bold text-slate-400 uppercase tracking-[0.2em] mb-2">Comentários</label>
                <textarea
                    id="comments"
                    value={comments}
                    onChange={(e) => setComments(e.target.value)}
                    rows={2}
