                    placeholder="Observações importantes..."
                />
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t border-slate-50">
                <button type="button" onClick={onClose} className="px-6 py-3 bg-white text-slate-600 border border-slate-200 rounded-2xl font-bold uppercase tracking-widest text-[10px]">Cancelar</button>
