                    {isSubmitting ? 'SALVANDO...' : 'CONFIRMAR'}
                </button>
            </div>
        </form>
    );
};

const Transactions: React.FC<{
  transactionType: 'checking_account' | 'credit_card';
  title: string;
}> = ({ transactionType, title }) => {
    // FIX: Destructure 'categories' from useAppData to fix 'Cannot find name categories' error on line 352
    const { transactions, accounts, categories, deleteTransaction, addTransaction, updateTransaction } = useAppData();
    const [isFormModalOpen, setIsFormModalOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);
    const [isPdfImportModalOpen, setIsPdfImportModalOpen] = useState(false);
    const [isPdfOptionsModalOpen, setIsPdfOptionsModalOpen] = useState(false);
    const [viewingAttachment, setViewingAttachment] = useState<Attachment | null>(null);
    const [transactionToEdit, setTransactionToEdit] = useState<Transaction | null>(null);
    const [selectedAccountFilter, setSelectedAccountFilter] = useState('');

    const filteredTransactions = useMemo(() => {
        return transactions.filter(t => {
            const matchesType = t.type === transactionType;
            const matchesAccount = selectedAccountFilter ? t.accountId === selectedAccountFilter : true;
            return matchesType && matchesAccount;
        });
    }, [transactions, transactionType, selectedAccountFilter]);

    const handleOpenForm = (transaction?: Transaction) => {
        setTransactionToEdit(transaction || null);
        setIsFormModalOpen(true);
    };

    const handleCloseForm = () => {
        setIsFormModalOpen(false);
        setTransactionToEdit(null);
    };

    const handleFormSubmit = async (data: Omit<Transaction, 'id'>, newAttachments: NewAttachment[]) => {
        if (transactionToEdit) {
            await updateTransaction({ ...transactionToEdit, ...data }, newAttachments);
        } else {
            await addTransaction(data, newAttachments);
        }
        handleCloseForm();
    };

    const handleDelete = async (id: string) => {
        if (window.confirm('Excluir este lançamento?')) {
            await deleteTransaction(id);
        }
    };

    const handleGeneratePdf = (options: { accountId: string; startDate: string; endDate: string }) => {
        const account = accounts.find(a => a.id === options.accountId);
        if (!account) return;

        const start = new Date(options.startDate);
        const end = new Date(options.endDate);
        start.setUTCHours(0,0,0,0);
        end.setUTCHours(23,59,59,999);

        const transactionsInPeriod = transactions.filter(t => {
            const tDate = new Date(t.date);
            return t.accountId === options.accountId && t.type === transactionType && tDate >= start && tDate <= end;
        });

        generateTransactionsPDF({
            account,
            period: { start: options.startDate, end: options.endDate },
            transactionsInPeriod,
            allTransactions: transactions,
            transactionType,
            title
        });
        setIsPdfOptionsModalOpen(false);
    };

    return (
        <div className="space-y-10">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
                <div>
                    <h1 className="text-4xl font-[800] text-slate-900 tracking-tight">{title}</h1>
                    <p className="text-slate-500 mt-2 font-medium tracking-wide">Gerenciamento detalhado de lançamentos.</p>
                </div>
                <div className="flex flex-wrap gap-3 w-full sm:w-auto">
                    <button onClick={() => setIsPdfOptionsModalOpen(true)} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-5 py-3.5 bg-white text-slate-700 border border-slate-200 rounded-2xl hover:bg-slate-50 font-bold uppercase tracking-widest text-[10px] shadow-sm">
                        <Download size={18} className="text-[#c5a059]" />
                        Exportar
                    </button>
                    <button onClick={() => handleOpenForm()} className="btn-premium-navy flex-1 sm:flex-none flex items-center justify-center gap-2 px-8 py-3.5 text-white rounded-2xl font-extrabold uppercase tracking-widest text-[10px] shadow-lg">
                        <Plus size={20} className="text-[#c5a059]" />
                        NOVO LANÇAMENTO
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-[2.5rem] premium-shadow border border-slate-50 overflow-hidden">
                <div className="p-8 border-b border-slate-50 bg-slate-50/20 flex items-center gap-4">
                    <Filter size={16} className="text-[#c5a059]" />
                    <select 
                        value={selectedAccountFilter} 
                        onChange={(e) => setSelectedAccountFilter(e.target.value)}
                        className="bg-transparent border-none focus:ring-0 text-xs font-extrabold text-slate-400 uppercase tracking-widest cursor-pointer"
                    >
                        <option value="">Filtrar: Todas as Contas</option>
                        {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead>
                            <tr className="bg-slate-50/10">
                                <th className="p-6 text-[10px] font-extrabold text-slate-400 uppercase tracking-[0.25em]">Data</th>
                                <th className="p-6 text-[10px] font-extrabold text-slate-400 uppercase tracking-[0.25em]">Descrição / Categoria</th>
                                <th className="p-6 text-[10px] font-extrabold text-slate-400 uppercase tracking-[0.25em] text-right">Valor</th>
                                <th className="p-6 text-[10px] font-extrabold text-slate-400 uppercase tracking-[0.25em] text-right">Ações</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredTransactions.length === 0 ? (
                                <tr>
                                    <td colSpan={4} className="p-16 text-center">
                                        <Wallet className="mx-auto h-12 w-12 text-slate-200" />
                                        <p className="text-slate-400 mt-6 font-extrabold uppercase tracking-widest text-[11px]">Nenhum lançamento registrado.</p>
                                    </td>
                                </tr>
                            ) : (
                                filteredTransactions.map(t => (
                                    <tr key={t.id} className="border-b border-slate-50 last:border-b-0 hover:bg-slate-50/30 transition-colors">
                                        <td className="p-6 text-sm font-semibold text-slate-500 tabular-nums">{formatDate(t.date)}</td>
                                        <td className="p-6">
                                            <div className="flex flex-col">
                                                <span className="font-bold text-slate-900 tracking-tight">{t.description || '-'}</span>
                                                <div className="flex items-center gap-2 mt-1">
                                                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                                        {categories.find(c => c.id === t.categoryId)?.name || 'S/ CAT'}
                                                    </span>
                                                    {t.comments && <MessageSquare size={12} className="text-[#c5a059]" />}
                                                </div>
                                            </div>
                                        </td>
                                        <td className={`p-6 text-right font-black text-base tabular-nums ${t.nature === TransactionNature.RECEITA ? 'text-emerald-600' : 'text-slate-900'}`}>
                                            {t.nature === TransactionNature.RECEITA ? '+' : '-'} {formatCurrency(t.value)}
                                        </td>
                                        <td className="p-6 text-right">
                                            <div className="flex justify-end gap-1">
                                                <button onClick={() => handleOpenForm(t)} className="p-3 text-slate-300 hover:text-[#c5a059] rounded-xl transition-all"><Edit size={18} /></button>
                                                <button onClick={() => handleDelete(t.id)} className="p-3 text-slate-300 hover:text-rose-600 rounded-xl transition-all"><Trash2 size={18} /></button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            <Modal isOpen={isFormModalOpen} onClose={handleCloseForm} title={transactionToEdit ? 'Alterar Lançamento' : 'Novo Lançamento'}>
                <TransactionForm onSubmit={handleFormSubmit} onClose={handleCloseForm} transactionToEdit={transactionToEdit} transactionType={transactionType} />
            </Modal>
            <PdfOptionsModal isOpen={isPdfOptionsModalOpen} onClose={() => setIsPdfOptionsModalOpen(false)} onSubmit={handleGeneratePdf} />
        </div>
    );
};

export default Transactions;

