import { Plus, Edit, Trash2, Landmark, X } from 'lucide-react';

const BankAccountForm: React.FC<{
  onSubmit: (account: Omit<BankAccount, 'id'>) => Promise<void>;
  onClose: () => void;
  accountToEdit?: BankAccount | null;
}> = ({ onSubmit, onClose, accountToEdit }) => {
  const [name, setName] = useState(accountToEdit?.name || '');
  const [type, setType] = useState<AccountType>(accountToEdit?.type || AccountType.CONTA_CORRENTE);
  const [initialBalance, setInitialBalance] = useState(accountToEdit?.initialBalance || 0);
  const [dataAbertura, setDataAbertura] = useState(accountToEdit?.dataAbertura || new Date().toISOString().split('T')[0]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !dataAbertura) return;
    setIsSubmitting(true);
    await onSubmit({ name, type, initialBalance, dataAbertura });
    setIsSubmitting(false);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4 sm:space-y-6">
        <input value={name} onChange={(e) => setName(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium" placeholder="Nome da Conta" />
        <select value={type} onChange={(e) => setType(e.target.value as AccountType)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-semibold">
          <option value={AccountType.CONTA_CORRENTE}>Conta Corrente</option>
          <option value={AccountType.CONTA_POUPANCA}>Conta Poupança</option>
        </select>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <input type="date" value={dataAbertura} onChange={(e) => setDataAbertura(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium" />
          <CurrencyInput value={initialBalance} onChange={setInitialBalance} />
        </div>
        <div className="flex justify-end gap-3 pt-4">
            <button type="button" onClick={onClose} className="px-6 py-3 bg-white text-slate-600 border border-slate-200 rounded-xl font-bold uppercase text-[10px]">Cancelar</button>
            <button type="submit" disabled={isSubmitting} className="btn-premium-gold px-8 py-3 text-white rounded-xl font-extrabold uppercase text-[10px] shadow-lg">Confirmar</button>
        </div>
    </form>
  );
};

const BankAccounts: React.FC = () => {
  const { accounts, addAccount, updateAccount, deleteAccount, calculateCurrentBalance, addTransaction, categories } = useAppData();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [accountToEdit, setAccountToEdit] = useState<BankAccount | null>(null);
  const [activeActionId, setActiveActionId] = useState<string | null>(null);

  const handleOpenModal = (account?: BankAccount) => {
    setAccountToEdit(account || null);
    setIsModalOpen(true);
    setActiveActionId(null);
  };

  const handleSubmit = async (data: Omit<BankAccount, 'id'>) => {
    if (accountToEdit) {
      await updateAccount({ ...accountToEdit, ...data });
    } else {
      const newAccount = await addAccount(data);
      if (newAccount && data.initialBalance > 0) {
          const cat = categories.find(c => c.type === CategoryType.RECEITA);
          if (cat) await addTransaction({ description: 'Saldo Inicial', nature: TransactionNature.RECEITA, accountId: newAccount.id, categoryId: cat.id, date: data.dataAbertura, value: data.initialBalance, type: 'checking_account' });
      }
    }
    setIsModalOpen(false);
  };

  const handleDelete = async (id: string) => {
    if(window.confirm('Excluir esta conta e todo o histórico?')) {
      await deleteAccount(id);
      setActiveActionId(null);
    }
  }

  return (
    <div className="space-y-6 sm:space-y-10">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl sm:text-4xl font-[800] text-slate-900 tracking-tight">Custódia Bancária</h1>
          <p className="text-sm sm:text-base text-slate-500 mt-1 sm:mt-2 font-medium tracking-wide">Gerenciamento de ativos.</p>
        </div>
        <button onClick={() => handleOpenModal()} className="btn-premium-navy flex items-center justify-center gap-2 px-6 py-3.5 text-white rounded-xl font-bold uppercase tracking-widest text-[9px] sm:text-[10px] shadow-2xl w-full sm:w-auto active:scale-95 transition-transform">
          <Plus size={18} className="text-[#c5a059]" /> Adicionar Conta
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-8">
        {accounts.map(acc => (
          <div 
            key={acc.id} 
            className="bg-white p-6 sm:p-8 rounded-2xl sm:rounded-[2.5rem] premium-shadow border border-slate-50 card-hover group active:bg-slate-50 transition-colors"
            onClick={() => setActiveActionId(activeActionId === acc.id ? null : acc.id)}
          >
            <div className="flex justify-between items-start">
              <div className="flex items-center gap-3 sm:gap-5">
                <div className="bg-slate-900 p-3 sm:p-4 rounded-xl sm:rounded-2xl shadow-lg">
                   <Landmark className="w-5 h-5 sm:w-7 sm:h-7 text-[#c5a059]" />
                </div>
                <div>
                  <h3 className="font-[800] text-lg sm:text-xl text-slate-900 tracking-tight">{acc.name}</h3>
                  <p className="text-[9px] font-extrabold text-[#c5a059] uppercase mt-0.5">{acc.type}</p>
                </div>
              </div>
            </div>
            <div className="mt-6 sm:mt-8">
              <p className="text-[9px] font-extrabold text-slate-400 uppercase tracking-widest">Saldo Atual</p>
              <p className="text-2xl sm:text-4xl font-[800] text-slate-900 mt-1 sm:mt-2 tracking-tighter tabular-nums">{formatCurrency(calculateCurrentBalance(acc.id))}</p>
            </div>

            {/* Ações Mobile - Reveladas por toque */}
            <div className={`mt-6 pt-6 border-t border-slate-50 flex gap-2 sm:flex ${activeActionId === acc.id ? 'flex' : 'hidden sm:flex'} animate-scale-in`}>
                <button onClick={(e) => { e.stopPropagation(); handleOpenModal(acc); }} className="flex-1 sm:flex-none p-3 text-slate-400 hover:text-[#c5a059] bg-slate-50 sm:bg-transparent rounded-xl flex items-center justify-center gap-2 sm:gap-0"><Edit size={18} /><span className="sm:hidden text-[10px] font-bold uppercase">Editar</span></button>
                <button onClick={(e) => { e.stopPropagation(); handleDelete(acc.id); }} className="flex-1 sm:flex-none p-3 text-slate-400 hover:text-rose-600 bg-rose-50 sm:bg-transparent rounded-xl flex items-center justify-center gap-2 sm:gap-0"><Trash2 size={18} /><span className="sm:hidden text-[10px] font-bold uppercase">Excluir</span></button>
                {activeActionId === acc.id && <button onClick={(e) => { e.stopPropagation(); setActiveActionId(null); }} className="sm:hidden p-3 bg-slate-100 text-slate-400 rounded-xl"><X size={18} /></button>}
            </div>
          </div>
        ))}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={accountToEdit ? 'Alterar' : 'Nova Conta'}>
        <BankAccountForm onSubmit={handleSubmit} onClose={() => setIsModalOpen(false)} accountToEdit={accountToEdit} />
      </Modal>
    </div>
  );
};

export default BankAccounts;

import React, { useState } from 'react';
import { useAppData } from '../../hooks/useAppData';
import { supabase } from '../../supabase/client';
import { formatDate } from '../../utils/formatters';
import { Plus, Trash2, Eye, FileText, ShieldCheck } from 'lucide-react';

const Documents: React.FC = () => {
    const { documents, deleteDocument } = useAppData();

    const getPublicUrl = (storagePath: string) => {
        const { data } = supabase.storage.from('attachments').getPublicUrl(storagePath);
        return data.publicUrl;
    }

    const handleDelete = async (id: string) => {
        if(window.confirm('Excluir documento?')) await deleteDocument(id);
    }

    return (
        <div className="space-y-6 sm:space-y-10">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 sm:gap-6">
                <div>
                    <h1 className="text-2xl sm:text-4xl font-[800] text-slate-900 tracking-tight">Cofre Digital</h1>
                    <p className="text-sm sm:text-base text-slate-500 mt-1 sm:mt-2 font-medium tracking-wide">Arquivamento seguro.</p>
                </div>
                <button className="btn-premium-navy flex items-center justify-center gap-2 px-6 py-3.5 text-white rounded-xl font-extrabold uppercase text-[10px] shadow-lg w-full sm:w-auto active:scale-95 transition-transform">
                    <Plus size={18} className="text-[#c5a059]" /> Novo Arquivo
                </button>
            </div>

            <div className="grid grid-cols-1 xs:grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4 sm:gap-8">
                {documents.length === 0 ? (
                    <div className="col-span-full text-center py-20 bg-white rounded-2xl sm:rounded-[2.5rem] premium-shadow border border-dashed border-slate-200">
                        <FileText className="mx-auto h-12 w-12 text-slate-200" />
                        <p className="text-slate-400 mt-4 font-extrabold uppercase tracking-widest text-[9px] sm:text-[11px]">Vazio.</p>
                    </div>
                ) : documents.map(doc => (
                    <div key={doc.id} className="bg-white rounded-2xl sm:rounded-[2.5rem] premium-shadow border border-slate-50 overflow-hidden group active:scale-[0.98] transition-transform">
                        <a href={getPublicUrl(doc.storage_path)} target="_blank" rel="noopener noreferrer" className="block bg-slate-100 h-40 sm:h-52 relative">
                            <img src={getPublicUrl(doc.storage_path)} alt={doc.title} className="h-full w-full object-cover" />
                            <div className="absolute inset-0 bg-slate-900/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <Eye className="text-white w-8 h-8" />
                            </div>
                        </a>
                        <div className="p-4 sm:p-6">
                            <h3 className="font-bold text-slate-900 tracking-tight text-sm sm:text-lg truncate">{doc.title}</h3>
                            <p className="text-[9px] font-black text-[#c5a059] uppercase tracking-widest mt-1">{formatDate(doc.created_at)}</p>
                            <div className="mt-4 pt-4 border-t border-slate-50 flex justify-end">
                                 <button onClick={(e) => { e.preventDefault(); handleDelete(doc.id); }} className="p-2 text-slate-300 hover:text-rose-600 transition-colors"><Trash2 size={18} /></button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default Documents;

import React, { useState } from 'react';
import Categories from './components/pages/Categories';
import BankAccounts from './components/pages/BankAccounts';
import Transactions from './components/pages/Transactions';
import Reports from './components/pages/Reports';
import Documents from './components/pages/Documents';
import Funcionamento from './components/pages/Funcionamento';
import CommentsReport from './components/pages/CommentsReport';
import Console from './components/ui/Console';
import AIChat from './components/ai/AIChat';
import { useAppData } from './hooks/useAppData';
import { Menu, X, Landmark, List, CreditCard, LayoutDashboard, Wallet, Loader2, FileText, Activity, MessageSquare, ShieldCheck } from 'lucide-react';

type Page = 'Dashboard' | 'Conta Bancária' | 'Categorias' | 'Conta Corrente' | 'Cartão de Crédito' | 'Documentos' | 'Funcionamento' | 'Comentários';

const App: React.FC = () => {
  const [activePage, setActivePage] = useState<Page>('Dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const { isLoading: isDataLoading } = useAppData();

  if (isDataLoading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-900">
        <div className="text-center p-4">
          <Loader2 className="w-12 h-12 text-[#c5a059] animate-spin mx-auto" />
          <p className="mt-6 text-sm sm:text-xl font-light text-slate-300 tracking-[0.2em] uppercase">Autenticando...</p>
        </div>
      </div>
    );
  }

  const renderPage = () => {
    switch (activePage) {
      case 'Categorias':
        return <Categories />;
      case 'Conta Bancária':
        return <BankAccounts />;
      case 'Conta Corrente':
        return <Transactions transactionType="checking_account" title="Conta Corrente" />;
      case 'Cartão de Crédito':
        return <Transactions transactionType="credit_card" title="Cartão de Crédito" />;
      case 'Dashboard':
        return <Reports />;
      case 'Documentos':
        return <Documents />;
      case 'Funcionamento':
        return <Funcionamento />;
      case 'Comentários':
        return <CommentsReport />;
      default:
        return <Reports />;
    }
  };

  const menuItems: { name: Page; icon: React.ReactNode }[] = [
    { name: 'Dashboard', icon: <LayoutDashboard className="w-5 h-5" /> },
    { name: 'Conta Corrente', icon: <Wallet className="w-5 h-5" /> },
    { name: 'Cartão de Crédito', icon: <CreditCard className="w-5 h-5" /> },
    { name: 'Comentários', icon: <MessageSquare className="w-5 h-5" /> },
    { name: 'Documentos', icon: <FileText className="w-5 h-5" /> },
    { name: 'Conta Bancária', icon: <Landmark className="w-5 h-5" /> },
    { name: 'Categorias', icon: <List className="w-5 h-5" /> },
    { name: 'Funcionamento', icon: <Activity className="w-5 h-5" /> },
  ];

  const NavLink: React.FC<{ page: Page, icon: React.ReactNode }> = ({ page, icon }) => (
    <li key={page}>
      <a
        href="#"
        onClick={(e) => {
          e.preventDefault();
          setActivePage(page);
          setIsSidebarOpen(false);
        }}
        className={`flex items-center gap-3.5 p-3.5 rounded-xl transition-all duration-300 font-semibold active:scale-95 ${
          activePage === page
            ? 'sidebar-item-active text-white scale-[1.02]'
            : 'text-slate-400 hover:bg-slate-800 hover:text-white'
        }`}
      >
        <span className={activePage === page ? 'text-white' : 'text-[#c5a059]'}>
          {icon}
        </span>
        <span className="tracking-tight text-sm sm:text-base">{page}</span>
      </a>
    </li>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar - Oculta em Mobile via translateX */}
      <aside
        className={`bg-slate-900 w-72 min-h-screen p-6 flex flex-col transition-transform duration-500 ease-in-out fixed lg:relative lg:translate-x-0 z-50 shadow-2xl ${
          isSidebarOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        <div className="flex items-center gap-4 pb-8 mb-4 border-b border-slate-800">
          <div className="bg-gradient-to-br from-[#c5a059] to-[#d9b36a] p-2 rounded-xl shadow-lg">
            <ShieldCheck className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-lg font-extrabold text-white tracking-tight">Curatela</h1>
            <p className="text-[9px] text-[#c5a059] font-bold uppercase tracking-[0.25em] leading-none mt-1">Sovereign Trust</p>
          </div>
        </div>

        <nav className="flex-1 overflow-y-auto no-scrollbar">
          <ul className="space-y-1.5">
            {menuItems.map(item => <NavLink key={item.name} page={item.name} icon={item.icon} />)}
          </ul>
        </nav>

        <div className="border-t border-slate-800 pt-6 mt-6">
            <div className="bg-slate-800/50 p-3 rounded-2xl border border-slate-700/50">
                <p className="text-[9px] text-[#c5a059] font-extrabold uppercase tracking-[0.2em] text-center">Proteção Garantida</p>
            </div>
            <p className="text-center text-[9px] text-slate-500 mt-4 font-bold uppercase tracking-[0.15em]">Versão Premium 2.5</p>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden relative">
        {/* Mobile Header - Visível apenas em telas pequenas */}
        <header className="bg-white/80 backdrop-blur-xl border-b border-slate-200 p-4 flex items-center justify-between lg:hidden sticky top-0 z-40">
          <div className="flex items-center gap-3">
            <div className="bg-slate-900 p-1.5 rounded-lg">
              <ShieldCheck className="w-5 h-5 text-[#c5a059]" />
            </div>
            <h1 className="text-base font-extrabold text-slate-900 tracking-tight">Curatela Contas</h1>
          </div>
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)} 
            className="p-2 text-slate-600 active:bg-slate-100 rounded-lg transition-colors"
          >
            {isSidebarOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </header>

        <main className="flex-1 overflow-y-auto p-4 sm:p-8 lg:p-10 bg-slate-50 no-scrollbar">
          <div className="max-w-7xl mx-auto animate-slide-up pb-20 lg:pb-0">
            {renderPage()}
          </div>
        </main>
      </div>

      {/* Overlay - Fecha sidebar no toque fora */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 lg:hidden transition-opacity duration-500" 
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}

      <Console />
      <AIChat />
    </div>
  );
};

export default App;

