        className="bg-white rounded-[2rem] sm:rounded-[2.5rem] premium-shadow w-full max-w-lg animate-scale-in flex flex-col max-h-[92vh] border border-slate-100 overflow-hidden"
        onClick={(e) => e.stopPropagation()}
