import React, { createContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { BankAccount, Category, Transaction, Document, Attachment, NewAttachment, KeepAliveLog } from '../types';
import { supabase, base64ToBlob } from '../supabase/client';

interface AppContextType {
  isLoading: boolean;
  accounts: BankAccount[];
  addAccount: (account: Omit<BankAccount, 'id'>) => Promise<BankAccount | null>;
  updateAccount: (account: BankAccount) => Promise<void>;
  deleteAccount: (id: string) => Promise<void>;
  getAccountById: (id: string) => BankAccount | undefined;

  categories: Category[];
  addCategory: (category: Omit<Category, 'id'>) => Promise<void>;
  addCategoriesBatch: (categories: Omit<Category, 'id'>[]) => Promise<void>;
  updateCategory: (category: Category) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;

  transactions: Transaction[];
  addTransaction: (transaction: Omit<Transaction, 'id'>, newAttachments?: NewAttachment[]) => Promise<void>;
  addTransactionsBatch: (transactions: Omit<Transaction, 'id'>[]) => Promise<void>;
  updateTransaction: (transaction: Transaction, newAttachments?: NewAttachment[]) => Promise<void>;
  deleteTransaction: (id: string) => Promise<void>;

  documents: Document[];
  addDocument: (title: string, fileName: string, base64Data: string) => Promise<void>;
  deleteDocument: (id: string) => Promise<void>;

  keepAliveLogs: KeepAliveLog[];

  calculateCurrentBalance: (accountId: string) => number;
}

export const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [keepAliveLogs, setKeepAliveLogs] = useState<KeepAliveLog[]>([]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [accountsRes, categoriesRes, transactionsRes, documentsRes, keepAliveLogsRes] = await Promise.all([
        supabase.from('accounts').select('*'),
        supabase.from('categories').select('*'),
        supabase.from('transactions').select('*').order('date', { ascending: false }),
        supabase.from('documents').select('*').order('created_at', { ascending: false }),
        supabase.from('keep_alive_logs').select('*').order('pinged_at', { ascending: false })
      ]);

      if (accountsRes.error) console.error("Error fetching accounts:", accountsRes.error.message || accountsRes.error);
      if (categoriesRes.error) console.error("Error fetching categories:", categoriesRes.error.message || categoriesRes.error);
      if (transactionsRes.error) console.error("Error fetching transactions:", transactionsRes.error.message || transactionsRes.error);
      if (documentsRes.error) console.error("Error fetching documents:", documentsRes.error.message || documentsRes.error);
      if (keepAliveLogsRes.error) console.error("Error fetching logs:", keepAliveLogsRes.error.message || keepAliveLogsRes.error);

      const typedAccounts = (accountsRes.data || []).map(a => ({...a, dataAbertura: a.dataAbertura?.split('T')[0] || new Date().toISOString().split('T')[0]}));
      const typedTransactions = (transactionsRes.data || []).map(t => ({...t, date: t.date?.split('T')[0] || new Date().toISOString().split('T')[0]}));

      setAccounts(typedAccounts);
      setCategories(categoriesRes.data || []);
      setTransactions(typedTransactions);
      setDocuments(documentsRes.data || []);
      setKeepAliveLogs(keepAliveLogsRes.data || []);

    } catch (error: any)
    {
      console.error("Critical error in fetchData:", error.message || error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Accounts CRUD
  const addAccount = async (accountData: Omit<BankAccount, 'id'>): Promise<BankAccount | null> => {
    const newAccount = { ...accountData, id: crypto.randomUUID() };
    const { data, error } = await supabase.from('accounts').insert(newAccount).select();
    if (error) {
      console.error("Error adding account:", error.message);
      return null;
    }
    if (data) {
      const createdAccount = data[0];
      setAccounts(prev => [...prev, createdAccount]);
      return createdAccount;
    }
    return null;
  };
  const updateAccount = async (updatedAccount: BankAccount) => {
    const { error } = await supabase.from('accounts').update(updatedAccount).eq('id', updatedAccount.id);
    if (error) return console.error("Error updating account:", error.message);
    setAccounts(prev => prev.map(acc => acc.id === updatedAccount.id ? updatedAccount : acc));
  };
  const deleteAccount = async (id: string) => {
    const { error } = await supabase.from('accounts').delete().eq('id', id);
    if (error) return console.error("Error deleting account:", error.message);
    setAccounts(prev => prev.filter(acc => acc.id !== id));
  };
  const getAccountById = (id: string) => accounts.find(acc => acc.id === id);

  // Categories CRUD
  const addCategory = async (categoryData: Omit<Category, 'id'>) => {
    const newCategory = { ...categoryData, id: crypto.randomUUID() };
    const { error } = await supabase.from('categories').insert(newCategory);
    if (error) return console.error("Error adding category:", error.message);
    setCategories(prev => [...prev, newCategory]);
  };
  const addCategoriesBatch = async (categoriesData: Omit<Category, 'id'>[]) => {
    const newCategories = categoriesData.map(c => ({ ...c, id: crypto.randomUUID() }));
    const { error } = await supabase.from('categories').insert(newCategories);
    if (error) {
        console.error("Error adding categories in batch:", error.message);
        throw error;
    }
    setCategories(prev => [...prev, ...newCategories].sort((a, b) => a.name.localeCompare(b.name)));
  };
  const updateCategory = async (updatedCategory: Category) => {
    const { error } = await supabase.from('categories').update(updatedCategory).eq('id', updatedCategory.id);
    if (error) return console.error("Error updating category:", error.message);
    setCategories(prev => prev.map(cat => cat.id === updatedCategory.id ? updatedCategory : cat));
  };
  const deleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) {
      console.error("Error deleting category:", error.message);
      throw error;
    }
    setCategories(prev => prev.filter(cat => cat.id !== id));
  };

  // Transactions CRUD
  const handleAttachmentUpload = async (newAttachments: NewAttachment[]): Promise<Attachment[]> => {
    const uploadedAttachments: Attachment[] = [];
    for (const attachment of newAttachments) {
      const sanitizedName = attachment.name.replace(/[^a-zA-Z0-9.-]/g, '_');
      // Alterado para não usar prefixo 'public/' que pode causar erros de permissão de pasta
      const filePath = `${crypto.randomUUID()}-${sanitizedName}`;

      console.log(`Iniciando upload de anexo: ${filePath}`);
      const { error: uploadError } = await supabase.storage
        .from('attachments')
        .upload(filePath, base64ToBlob(attachment.data, 'image/jpeg'));

      if (uploadError) {
        console.error('Error uploading attachment:', uploadError.message);
        continue;
      }

      const { data: { publicUrl } } = supabase.storage.from('attachments').getPublicUrl(filePath);
      console.log(`Upload concluído com sucesso. URL: ${publicUrl}`);
      uploadedAttachments.push({ id: attachment.id, name: attachment.name, url: publicUrl });
    }
    return uploadedAttachments;
  }

  const addTransaction = async (transactionData: Omit<Transaction, 'id'>, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const newTransaction = { ...transactionData, id: crypto.randomUUID(), attachments: uploadedAttachments };
    const { error } = await supabase.from('transactions').insert(newTransaction);
    if (error) return console.error("Error adding transaction:", error.message);
    setTransactions(prev => [newTransaction, ...prev].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const addTransactionsBatch = async (transactionsData: Omit<Transaction, 'id'>[]) => {
    const newTransactions = transactionsData.map(t => ({ ...t, id: crypto.randomUUID() }));
    const { error } = await supabase.from('transactions').insert(newTransactions);
    if (error) {
        console.error("Error adding transactions in batch:", error.message);
        throw error;
    }
    setTransactions(prev => [...prev, ...newTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const updateTransaction = async (updatedTransactionData: Transaction, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    // Combina anexos que já existiam e que não foram removidos com os novos
    const finalAttachments = [...(updatedTransactionData.attachments || []), ...uploadedAttachments];
    const transactionToUpdate = { ...updatedTransactionData, attachments: finalAttachments };
    const { error } = await supabase.from('transactions').update(transactionToUpdate).eq('id', transactionToUpdate.id);
    if (error) return console.error("Error updating transaction:", error.message);
    setTransactions(prev => prev.map(t => t.id === transactionToUpdate.id ? transactionToUpdate : t).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const deleteTransaction = async (id: string) => {
    const transactionToDelete = transactions.find(t => t.id === id);
    if (transactionToDelete?.attachments) {
      for (const attachment of transactionToDelete.attachments) {
        try {
          const url = new URL(attachment.url);
          const storagePath = url.pathname.split('/attachments/')[1];
          await supabase.storage.from('attachments').remove([storagePath]);
        } catch(e) { console.error("Failed to delete attachment from storage:", e) }
      }
    }
    const { error } = await supabase.from('transactions').delete().eq('id', id);
    if (error) {
        console.error("Error deleting transaction:", error.message);
        throw error;
    }
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  // Documents CRUD
  const addDocument = async (title: string, fileName: string, base64Data: string) => {
      const sanitizedName = fileName.replace(/[^a-zA-Z0-9.-]/g, '_');
      const storagePath = `documents/${crypto.randomUUID()}-${sanitizedName}`;

      const { error: uploadError } = await supabase.storage
          .from('attachments')
          .upload(storagePath, base64ToBlob(base64Data, 'image/jpeg'));

      if (uploadError) {
          console.error("Error uploading document:", uploadError.message);
          throw uploadError;
      }

      const newDocument = { title, file_name: fileName, storage_path: storagePath };
      const { data, error } = await supabase.from('documents').insert(newDocument).select();
      if (error) {
        console.error("Error saving document record:", error.message);
        await supabase.storage.from('attachments').remove([storagePath]);
        throw error;
      }
      if (data) setDocuments(prev => [data[0], ...prev]);
  };
  const deleteDocument = async (id: string) => {
      const docToDelete = documents.find(d => d.id === id);
      if (!docToDelete) return;

      const { error: storageError } = await supabase.storage.from('attachments').remove([docToDelete.storage_path]);
      if (storageError) console.error("Error deleting document from storage:", storageError.message);

      const { error: dbError } = await supabase.from('documents').delete().eq('id', id);
      if (dbError) return console.error("Error deleting document from DB:", dbError.message);

      setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const calculateCurrentBalance = useMemo(() => (accountId: string): number => {
    const account = accounts.find(acc => acc.id === accountId);
    if (!account) return 0;

    const accountTransactions = transactions.filter(t => t.accountId === accountId && t.type === 'checking_account');

    const balance = accountTransactions.reduce((acc, curr) => {
      if (curr.nature === 'RECEITA') {
        return acc + curr.value;
      }
      return acc - curr.value;
    }, 0);

    return balance;
  }, [accounts, transactions]);

  const contextValue = {
    isLoading,
    accounts, addAccount, updateAccount, deleteAccount, getAccountById,
    categories, addCategory, addCategoriesBatch, updateCategory, deleteCategory,
    transactions, addTransaction, addTransactionsBatch, updateTransaction, deleteTransaction,
    documents, addDocument, deleteDocument,
    keepAliveLogs,
    calculateCurrentBalance,
  };

  return (
    <AppContext.Provider value={contextValue}>
      {children}
    </AppContext.Provider>
  );
};

import { Transaction, BankAccount } from '../types';
import { formatCurrency, formatDate } from './formatters';

declare global {
    interface Window {
        jspdf: any;
    }
}

interface PdfOptions {
    account: BankAccount;
    period: { start: string; end: string };
    transactionsInPeriod: Transaction[];
    allTransactions: Transaction[];
    transactionType: 'checking_account' | 'credit_card';
    title: string;
}

const calculateBalanceUpToDate = (accountId: string, upToDate: Date, allTransactions: Transaction[]): number => {
    const previousTransactions = allTransactions.filter(t => {
        const tDate = new Date(t.date);
        return t.accountId === accountId && t.type === 'checking_account' && tDate < upToDate;
    });

    const balance = previousTransactions.reduce((acc, curr) => {
        if (curr.nature === 'RECEITA') {
            return acc + curr.value;
        }
        return acc - curr.value;
    }, 0);

    return balance;
};


export const generateTransactionsPDF = (options: PdfOptions) => {
    const { account, period, transactionsInPeriod, allTransactions, transactionType, title } = options;
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation: 'portrait' });

    const isCheckingAccount = transactionType === 'checking_account';

    // Header
    doc.setFontSize(18);
    doc.text(isCheckingAccount ? 'Extrato de Conta Corrente' : title, 14, 22);
    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(`Conta: ${account.name}`, 14, 29);
    doc.text(`Período: ${formatDate(period.start)} a ${formatDate(period.end)}`, 14, 36);

    let startY = 50;
    let previousBalance = 0;

    if (isCheckingAccount) {
        const startOfDay = new Date(period.start);
        startOfDay.setUTCHours(0, 0, 0, 0);
        previousBalance = calculateBalanceUpToDate(account.id, startOfDay, allTransactions);

        const yesterday = new Date(period.start);
        yesterday.setUTCDate(yesterday.getUTCDate() - 1);
        doc.setFontSize(10);
        doc.setFont(undefined, 'bold');
        doc.text(`Saldo em ${formatDate(yesterday.toISOString())}: ${formatCurrency(previousBalance)}`, 14, 46);
        doc.setFont(undefined, 'normal');
    } else {
        startY = 42;
    }

    const tableColumn = isCheckingAccount
        ? ["Data", "Descrição", "Nº Nota", "C/D", "Valor", "Saldo"]
        : ["Data", "Descrição", "Nº Nota", "Saída (-)"];

    const tableRows: (string | number)[][] = [];
    let runningBalance = previousBalance;
    let totalEntradas = 0;
    let totalSaidas = 0;

    const sortedTransactions = [...transactionsInPeriod].sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedTransactions.forEach(t => {
        const entrada = t.nature === 'RECEITA' ? t.value : 0;
        const saida = t.nature === 'DESPESA' ? t.value : 0;

        runningBalance += entrada - saida;
        totalEntradas += entrada;
        totalSaidas += saida;

        const transactionData: (string|number)[] = [
            formatDate(t.date),
            t.description,
            t.numeroNota || '-',
        ];

        if (isCheckingAccount) {
            transactionData.push(t.nature === 'RECEITA' ? '+' : '-');
            transactionData.push(formatCurrency(t.value));
            transactionData.push(formatCurrency(runningBalance));
        } else {
            transactionData.push(saida > 0 ? formatCurrency(saida) : '-');
        }
        tableRows.push(transactionData);
    });

    doc.autoTable({
        head: [tableColumn],
        body: tableRows,
        startY: startY,
        theme: 'grid',
        headStyles: { fillColor: [37, 99, 235] }, // Blue
        columnStyles: isCheckingAccount ? {
            3: { cellWidth: 10, halign: 'center' } // Coluna C/D compacta (ajustado índice de 4 para 3)
        } : {},
        didDrawPage: (data: any) => {
            const pageCount = doc.internal.getNumberOfPages();
            doc.setFontSize(10);
            doc.text(`Página ${data.pageNumber} de ${pageCount}`, data.settings.margin.left, doc.internal.pageSize.height - 10);
        }
    });

    const finalY = doc.lastAutoTable.finalY + 10;
    doc.setFontSize(12);
    doc.text('Resumo do Período', 14, finalY);
    doc.setFontSize(10);

    let summaryY = finalY + 7;
    if (isCheckingAccount) {
        doc.text(`Saldo Anterior: ${formatCurrency(previousBalance)}`, 14, summaryY);
        summaryY += 7;
    }

    doc.text(`Total de Entradas: ${formatCurrency(totalEntradas)}`, 14, summaryY);
    summaryY += 7;
    doc.text(`Total de Saídas: ${formatCurrency(totalSaidas)}`, 14, summaryY);
    summaryY += 7;

    doc.setFontSize(11);
    doc.setFont(undefined, 'bold');

    if (isCheckingAccount) {
        const finalBalance = previousBalance + totalEntradas - totalSaidas;
        doc.text(`Saldo Final: ${formatCurrency(finalBalance)}`, 14, summaryY);
    } else {
        const totalFatura = totalSaidas - totalEntradas; // Total expenses minus payments/credits
        doc.text(`Total da Fatura: ${formatCurrency(totalFatura)}`, 14, summaryY);
    }

    const fileName = isCheckingAccount 
      ? `extrato_${account.name.toLowerCase().replace(/\s/g, '_')}.pdf`
      : `fatura_${account.name.toLowerCase().replace(/\s/g, '_')}.pdf`;

    doc.save(fileName);
};

export const generateCommentsPDF = (options: { 
    account: BankAccount,
    period: { start: string, end: string },
    transactions: Transaction[] 
}) => {
    const { account, period, transactions } = options;
    const { jsPDF } = window.jspdf;

    // PDF em modo Paisagem (Landscape)
    const doc = new jsPDF({ orientation: 'landscape' });
    const pageWidth = doc.internal.pageSize.getWidth();
    const margin = 14;

    // Cabeçalho do Relatório
    doc.setFontSize(18);
    doc.text('Relatório de Comentários e Observações', margin, 22);
    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(`Conta: ${account.name}`, margin, 29);
    doc.text(`Período: ${formatDate(period.start)} a ${formatDate(period.end)}`, margin, 36);

    let currentY = 45;

    // Ordena transações por data
    const sortedTransactions = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    if (sortedTransactions.length === 0) {
        doc.setFontSize(12);
        doc.setTextColor(0);
        doc.text('Nenhum comentário registrado para os filtros selecionados.', margin, currentY);
    } else {
        sortedTransactions.forEach((t) => {
            // Estrutura de Tabela por Comentário (Mandatório)
            doc.autoTable({
                startY: currentY,
                head: [[
                    { content: `NOME DA TRANSAÇÃO: ${t.description || 'Sem Descrição'}`, styles: { halign: 'left', cellWidth: 'auto' } },
                    { content: `DATA: ${formatDate(t.date)}`, styles: { halign: 'center', cellWidth: 40 } },
                    { content: `VALOR DA TRANSAÇÃO: ${formatCurrency(t.value)}`, styles: { halign: 'right', cellWidth: 60 } }
                ]],
                body: [[
                    { content: t.comments || 'Sem observações.', colSpan: 3, styles: { cellPadding: 5, fontStyle: 'italic' } }
                ]],
                theme: 'grid',
                headStyles: { 
                    fillColor: [75, 85, 99], // Gray-600
                    textColor: [255, 255, 255],
                    fontSize: 10,
                    fontStyle: 'bold'
                },
                bodyStyles: {
                    fontSize: 10,
                    textColor: [31, 41, 55], // Gray-800
                },
                margin: { left: margin, right: margin },
                tableWidth: pageWidth - (margin * 2),
            });

            currentY = doc.lastAutoTable.finalY + 10;

            // Gerencia quebra de página
            if (currentY > doc.internal.pageSize.getHeight() - 20) {
                doc.addPage();
                currentY = 20;
            }
        });
    }

    // Rodapé com numeração
    const pageCount = doc.internal.getNumberOfPages();
    for(let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(9);
        doc.setTextColor(150);
        doc.text(`Página ${i} de ${pageCount}`, pageWidth - margin - 20, doc.internal.pageSize.getHeight() - 10);
    }

    doc.save(`comentarios_${account.name.toLowerCase().replace(/\s/g, '_')}.pdf`);
};

import React, { createContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { BankAccount, Category, Transaction, Document, Attachment, NewAttachment, KeepAliveLog } from '../types';
import { supabase, base64ToBlob } from '../supabase/client';

interface AppContextType {
  isLoading: boolean;
  accounts: BankAccount[];
  addAccount: (account: Omit<BankAccount, 'id'>) => Promise<BankAccount | null>;
  updateAccount: (account: BankAccount) => Promise<void>;
  deleteAccount: (id: string) => Promise<void>;
  getAccountById: (id: string) => BankAccount | undefined;

  categories: Category[];
  addCategory: (category: Omit<Category, 'id'>) => Promise<void>;
  addCategoriesBatch: (categories: Omit<Category, 'id'>[]) => Promise<void>;
  updateCategory: (category: Category) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;

  transactions: Transaction[];
  addTransaction: (transaction: Omit<Transaction, 'id'>, newAttachments?: NewAttachment[]) => Promise<void>;
  addTransactionsBatch: (transactions: Omit<Transaction, 'id'>[]) => Promise<void>;
  updateTransaction: (transaction: Transaction, newAttachments?: NewAttachment[]) => Promise<void>;
  deleteTransaction: (id: string) => Promise<void>;

  documents: Document[];
  addDocument: (title: string, fileName: string, base64Data: string) => Promise<void>;
  deleteDocument: (id: string) => Promise<void>;

  keepAliveLogs: KeepAliveLog[];

  calculateCurrentBalance: (accountId: string) => number;
}

export const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [keepAliveLogs, setKeepAliveLogs] = useState<KeepAliveLog[]>([]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [accountsRes, categoriesRes, transactionsRes, documentsRes, keepAliveLogsRes] = await Promise.all([
        supabase.from('accounts').select('*'),
        supabase.from('categories').select('*'),
        supabase.from('transactions').select('*').order('date', { ascending: false }),
        supabase.from('documents').select('*').order('created_at', { ascending: false }),
        supabase.from('keep_alive_logs').select('*').order('pinged_at', { ascending: false })
      ]);

      if (accountsRes.error) console.error("Error fetching accounts:", accountsRes.error.message || accountsRes.error);
      if (categoriesRes.error) console.error("Error fetching categories:", categoriesRes.error.message || categoriesRes.error);
      if (transactionsRes.error) console.error("Error fetching transactions:", transactionsRes.error.message || transactionsRes.error);
      if (documentsRes.error) console.error("Error fetching documents:", documentsRes.error.message || documentsRes.error);
      if (keepAliveLogsRes.error) console.error("Error fetching logs:", keepAliveLogsRes.error.message || keepAliveLogsRes.error);

      const typedAccounts = (accountsRes.data || []).map(a => ({...a, dataAbertura: a.dataAbertura?.split('T')[0] || new Date().toISOString().split('T')[0]}));
      const typedTransactions = (transactionsRes.data || []).map(t => ({...t, date: t.date?.split('T')[0] || new Date().toISOString().split('T')[0]}));

      setAccounts(typedAccounts);
      setCategories(categoriesRes.data || []);
      setTransactions(typedTransactions);
      setDocuments(documentsRes.data || []);
      setKeepAliveLogs(keepAliveLogsRes.data || []);

    } catch (error: any)
    {
      console.error("Critical error in fetchData:", error.message || error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Accounts CRUD
  const addAccount = async (accountData: Omit<BankAccount, 'id'>): Promise<BankAccount | null> => {
    const newAccount = { ...accountData, id: crypto.randomUUID() };
    const { data, error } = await supabase.from('accounts').insert(newAccount).select();
    if (error) {
      console.error("Error adding account:", error.message);
      return null;
    }
    if (data) {
      const createdAccount = data[0];
      setAccounts(prev => [...prev, createdAccount]);
      return createdAccount;
    }
    return null;
  };
  const updateAccount = async (updatedAccount: BankAccount) => {
    const { error } = await supabase.from('accounts').update(updatedAccount).eq('id', updatedAccount.id);
    if (error) return console.error("Error updating account:", error.message);
    setAccounts(prev => prev.map(acc => acc.id === updatedAccount.id ? updatedAccount : acc));
  };
  const deleteAccount = async (id: string) => {
    const { error } = await supabase.from('accounts').delete().eq('id', id);
    if (error) return console.error("Error deleting account:", error.message);
    setAccounts(prev => prev.filter(acc => acc.id !== id));
  };
  const getAccountById = (id: string) => accounts.find(acc => acc.id === id);

  // Categories CRUD
  const addCategory = async (categoryData: Omit<Category, 'id'>) => {
    const newCategory = { ...categoryData, id: crypto.randomUUID() };
    const { error } = await supabase.from('categories').insert(newCategory);
    if (error) return console.error("Error adding category:", error.message);
    setCategories(prev => [...prev, newCategory]);
  };
  const addCategoriesBatch = async (categoriesData: Omit<Category, 'id'>[]) => {
    const newCategories = categoriesData.map(c => ({ ...c, id: crypto.randomUUID() }));
    const { error } = await supabase.from('categories').insert(newCategories);
    if (error) {
        console.error("Error adding categories in batch:", error.message);
        throw error;
    }
    setCategories(prev => [...prev, ...newCategories].sort((a, b) => a.name.localeCompare(b.name)));
  };
  const updateCategory = async (updatedCategory: Category) => {
    const { error } = await supabase.from('categories').update(updatedCategory).eq('id', updatedCategory.id);
    if (error) return console.error("Error updating category:", error.message);
    setCategories(prev => prev.map(cat => cat.id === updatedCategory.id ? updatedCategory : cat));
  };
  const deleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) {
      console.error("Error deleting category:", error.message);
      throw error;
    }
    setCategories(prev => prev.filter(cat => cat.id !== id));
  };

  // Transactions CRUD
  const handleAttachmentUpload = async (newAttachments: NewAttachment[]): Promise<Attachment[]> => {
    const uploadedAttachments: Attachment[] = [];
    for (const attachment of newAttachments) {
      const sanitizedName = attachment.name.replace(/[^a-zA-Z0-9.-]/g, '_');
      const filePath = `${crypto.randomUUID()}-${sanitizedName}`;

      console.log(`Iniciando upload de anexo: ${filePath}`);
      const { error: uploadError } = await supabase.storage
        .from('attachments')
        .upload(filePath, base64ToBlob(attachment.data, 'image/jpeg'), {
          contentType: 'image/jpeg',
          upsert: true
        });

      if (uploadError) {
        console.error('Error uploading attachment:', uploadError.message);
        continue;
      }

      const { data: { publicUrl } } = supabase.storage.from('attachments').getPublicUrl(filePath);
      console.log(`Upload concluído com sucesso. URL: ${publicUrl}`);
      uploadedAttachments.push({ id: attachment.id, name: attachment.name, url: publicUrl });
    }
    return uploadedAttachments;
  }

  const addTransaction = async (transactionData: Omit<Transaction, 'id'>, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const newTransaction = { ...transactionData, id: crypto.randomUUID(), attachments: uploadedAttachments };
    const { error } = await supabase.from('transactions').insert(newTransaction);
    if (error) return console.error("Error adding transaction:", error.message);
    setTransactions(prev => [newTransaction, ...prev].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const addTransactionsBatch = async (transactionsData: Omit<Transaction, 'id'>[]) => {
    const newTransactions = transactionsData.map(t => ({ ...t, id: crypto.randomUUID() }));
    const { error } = await supabase.from('transactions').insert(newTransactions);
    if (error) {
        console.error("Error adding transactions in batch:", error.message);
        throw error;
    }
    setTransactions(prev => [...prev, ...newTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const updateTransaction = async (updatedTransactionData: Transaction, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const finalAttachments = [...(updatedTransactionData.attachments || []), ...uploadedAttachments];
    const transactionToUpdate = { ...updatedTransactionData, attachments: finalAttachments };
    const { error } = await supabase.from('transactions').update(transactionToUpdate).eq('id', transactionToUpdate.id);
    if (error) return console.error("Error updating transaction:", error.message);
    setTransactions(prev => prev.map(t => t.id === transactionToUpdate.id ? transactionToUpdate : t).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const deleteTransaction = async (id: string) => {
    const transactionToDelete = transactions.find(t => t.id === id);
    if (transactionToDelete?.attachments) {
      for (const attachment of transactionToDelete.attachments) {
        try {
          const url = new URL(attachment.url);
          const storagePath = url.pathname.split('/attachments/')[1];
          await supabase.storage.from('attachments').remove([storagePath]);
        } catch(e) { console.error("Failed to delete attachment from storage:", e) }
      }
    }
    const { error } = await supabase.from('transactions').delete().eq('id', id);
    if (error) {
        console.error("Error deleting transaction:", error.message);
        throw error;
    }
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  // Documents CRUD
  const addDocument = async (title: string, fileName: string, base64Data: string) => {
      const sanitizedName = fileName.replace(/[^a-zA-Z0-9.-]/g, '_');
      const storagePath = `documents/${crypto.randomUUID()}-${sanitizedName}`;

      const { error: uploadError } = await supabase.storage
          .from('attachments')
          .upload(storagePath, base64ToBlob(base64Data, 'image/jpeg'), {
            contentType: 'image/jpeg',
            upsert: true
          });

      if (uploadError) {
          console.error("Error uploading document:", uploadError.message);
          throw uploadError;
      }

      const newDocument = { title, file_name: fileName, storage_path: storagePath };
      const { data, error } = await supabase.from('documents').insert(newDocument).select();
      if (error) {
        console.error("Error saving document record:", error.message);
        await supabase.storage.from('attachments').remove([storagePath]);
        throw error;
      }
      if (data) setDocuments(prev => [data[0], ...prev]);
  };
  const deleteDocument = async (id: string) => {
      const docToDelete = documents.find(d => d.id === id);
      if (!docToDelete) return;

      const { error: storageError } = await supabase.storage.from('attachments').remove([docToDelete.storage_path]);
      if (storageError) console.error("Error deleting document from storage:", storageError.message);

      const { error: dbError } = await supabase.from('documents').delete().eq('id', id);
      if (dbError) return console.error("Error deleting document from DB:", dbError.message);

      setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const calculateCurrentBalance = useMemo(() => (accountId: string): number => {
    const account = accounts.find(acc => acc.id === accountId);
    if (!account) return 0;

    const accountTransactions = transactions.filter(t => t.accountId === accountId && t.type === 'checking_account');

    const balance = accountTransactions.reduce((acc, curr) => {
      if (curr.nature === 'RECEITA') {
        return acc + curr.value;
      }
      return acc - curr.value;
    }, 0);

    return balance;
  }, [accounts, transactions]);

  const contextValue = {
    isLoading,
    accounts, addAccount, updateAccount, deleteAccount, getAccountById,
    categories, addCategory, addCategoriesBatch, updateCategory, deleteCategory,
    transactions, addTransaction, addTransactionsBatch, updateTransaction, deleteTransaction,
    documents, addDocument, deleteDocument,
    keepAliveLogs,
    calculateCurrentBalance,
  };

  return (
    <AppContext.Provider value={contextValue}>
      {children}
    </AppContext.Provider>
  );
};

import React, { createContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { BankAccount, Category, Transaction, Document, Attachment, NewAttachment, KeepAliveLog } from '../types';
import { supabase, base64ToBlob } from '../supabase/client';

interface AppContextType {
  isLoading: boolean;
  accounts: BankAccount[];
  addAccount: (account: Omit<BankAccount, 'id'>) => Promise<BankAccount | null>;
  updateAccount: (account: BankAccount) => Promise<void>;
  deleteAccount: (id: string) => Promise<void>;
  getAccountById: (id: string) => BankAccount | undefined;

  categories: Category[];
  addCategory: (category: Omit<Category, 'id'>) => Promise<void>;
  addCategoriesBatch: (categories: Omit<Category, 'id'>[]) => Promise<void>;
  updateCategory: (category: Category) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;

  transactions: Transaction[];
  addTransaction: (transaction: Omit<Transaction, 'id'>, newAttachments?: NewAttachment[]) => Promise<void>;
  addTransactionsBatch: (transactions: Omit<Transaction, 'id'>[]) => Promise<void>;
  updateTransaction: (transaction: Transaction, newAttachments?: NewAttachment[]) => Promise<void>;
  deleteTransaction: (id: string) => Promise<void>;

  documents: Document[];
  addDocument: (title: string, fileName: string, base64Data: string) => Promise<void>;
  deleteDocument: (id: string) => Promise<void>;

  keepAliveLogs: KeepAliveLog[];

  calculateCurrentBalance: (accountId: string) => number;
}

export const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [keepAliveLogs, setKeepAliveLogs] = useState<KeepAliveLog[]>([]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [accountsRes, categoriesRes, transactionsRes, documentsRes, keepAliveLogsRes] = await Promise.all([
        supabase.from('accounts').select('*'),
        supabase.from('categories').select('*'),
        supabase.from('transactions').select('*').order('id', { ascending: false }), // Ordem de Inclusão (Baseado no ID gerado ou timestamp interno)
        supabase.from('documents').select('*').order('created_at', { ascending: false }),
        supabase.from('keep_alive_logs').select('*').order('pinged_at', { ascending: false })
      ]);

      if (accountsRes.error) console.error("Error fetching accounts:", accountsRes.error.message || accountsRes.error);
      if (categoriesRes.error) console.error("Error fetching categories:", categoriesRes.error.message || categoriesRes.error);
      if (transactionsRes.error) console.error("Error fetching transactions:", transactionsRes.error.message || transactionsRes.error);
      if (documentsRes.error) console.error("Error fetching documents:", documentsRes.error.message || documentsRes.error);
      if (keepAliveLogsRes.error) console.error("Error fetching logs:", keepAliveLogsRes.error.message || keepAliveLogsRes.error);

      const typedAccounts = (accountsRes.data || []).map(a => ({...a, dataAbertura: a.dataAbertura?.split('T')[0] || new Date().toISOString().split('T')[0]}));
      const typedTransactions = (transactionsRes.data || []).map(t => ({...t, date: t.date?.split('T')[0] || new Date().toISOString().split('T')[0]}));

      setAccounts(typedAccounts);
      setCategories(categoriesRes.data || []);
      setTransactions(typedTransactions);
      setDocuments(documentsRes.data || []);
      setKeepAliveLogs(keepAliveLogsRes.data || []);

    } catch (error: any)
    {
      console.error("Critical error in fetchData:", error.message || error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Accounts CRUD
  const addAccount = async (accountData: Omit<BankAccount, 'id'>): Promise<BankAccount | null> => {
    const newAccount = { ...accountData, id: crypto.randomUUID() };
    const { data, error } = await supabase.from('accounts').insert(newAccount).select();
    if (error) {
      console.error("Error adding account:", error.message);
      return null;
    }
    if (data) {
      const createdAccount = data[0];
      setAccounts(prev => [...prev, createdAccount]);
      return createdAccount;
    }
    return null;
  };
  const updateAccount = async (updatedAccount: BankAccount) => {
    const { error } = await supabase.from('accounts').update(updatedAccount).eq('id', updatedAccount.id);
    if (error) return console.error("Error updating account:", error.message);
    setAccounts(prev => prev.map(acc => acc.id === updatedAccount.id ? updatedAccount : acc));
  };
  const deleteAccount = async (id: string) => {
    const { error } = await supabase.from('accounts').delete().eq('id', id);
    if (error) return console.error("Error deleting account:", error.message);
    setAccounts(prev => prev.filter(acc => acc.id !== id));
  };
  const getAccountById = (id: string) => accounts.find(acc => acc.id === id);

  // Categories CRUD
  const addCategory = async (categoryData: Omit<Category, 'id'>) => {
    const newCategory = { ...categoryData, id: crypto.randomUUID() };
    const { error } = await supabase.from('categories').insert(newCategory);
    if (error) return console.error("Error adding category:", error.message);
    setCategories(prev => [...prev, newCategory]);
  };
  const addCategoriesBatch = async (categoriesData: Omit<Category, 'id'>[]) => {
    const newCategories = categoriesData.map(c => ({ ...c, id: crypto.randomUUID() }));
    const { error } = await supabase.from('categories').insert(newCategories);
    if (error) {
        console.error("Error adding categories in batch:", error.message);
        throw error;
    }
    setCategories(prev => [...prev, ...newCategories].sort((a, b) => a.name.localeCompare(b.name)));
  };
  const updateCategory = async (updatedCategory: Category) => {
    const { error } = await supabase.from('categories').update(updatedCategory).eq('id', updatedCategory.id);
    if (error) return console.error("Error updating category:", error.message);
    setCategories(prev => prev.map(cat => cat.id === updatedCategory.id ? updatedCategory : cat));
  };
  const deleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) {
      console.error("Error deleting category:", error.message);
      throw error;
    }
    setCategories(prev => prev.filter(cat => cat.id !== id));
  };

  // Transactions CRUD
  const handleAttachmentUpload = async (newAttachments: NewAttachment[]): Promise<Attachment[]> => {
    const uploadedAttachments: Attachment[] = [];
    for (const attachment of newAttachments) {
      const sanitizedName = attachment.name.replace(/[^a-zA-Z0-9.-]/g, '_');
      const filePath = `${crypto.randomUUID()}-${sanitizedName}`;

      console.log(`Iniciando upload de anexo: ${filePath}`);
      const { error: uploadError } = await supabase.storage
        .from('attachments')
        .upload(filePath, base64ToBlob(attachment.data, 'image/jpeg'), {
          contentType: 'image/jpeg',
          upsert: true
        });

      if (uploadError) {
        console.error('Error uploading attachment:', uploadError.message);
        continue;
      }

      const { data: { publicUrl } } = supabase.storage.from('attachments').getPublicUrl(filePath);
      console.log(`Upload concluído com sucesso. URL: ${publicUrl}`);
      uploadedAttachments.push({ id: attachment.id, name: attachment.name, url: publicUrl });
    }
    return uploadedAttachments;
  }

  const addTransaction = async (transactionData: Omit<Transaction, 'id'>, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const newTransaction = { ...transactionData, id: crypto.randomUUID(), attachments: uploadedAttachments };
    const { error } = await supabase.from('transactions').insert(newTransaction);
    if (error) return console.error("Error adding transaction:", error.message);
    setTransactions(prev => [newTransaction, ...prev]);
  };
  const addTransactionsBatch = async (transactionsData: Omit<Transaction, 'id'>[]) => {
    const newTransactions = transactionsData.map(t => ({ ...t, id: crypto.randomUUID() }));
    const { error } = await supabase.from('transactions').insert(newTransactions);
    if (error) {
        console.error("Error adding transactions in batch:", error.message);
        throw error;
    }
    setTransactions(prev => [...newTransactions, ...prev]);
  };
  const updateTransaction = async (updatedTransactionData: Transaction, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const finalAttachments = [...(updatedTransactionData.attachments || []), ...uploadedAttachments];
    const transactionToUpdate = { ...updatedTransactionData, attachments: finalAttachments };
    const { error } = await supabase.from('transactions').update(transactionToUpdate).eq('id', transactionToUpdate.id);
    if (error) return console.error("Error updating transaction:", error.message);
    setTransactions(prev => prev.map(t => t.id === transactionToUpdate.id ? transactionToUpdate : t));
  };
  const deleteTransaction = async (id: string) => {
    const transactionToDelete = transactions.find(t => t.id === id);
    if (transactionToDelete?.attachments) {
      for (const attachment of transactionToDelete.attachments) {
        try {
          const url = new URL(attachment.url);
          const storagePath = url.pathname.split('/attachments/')[1];
          await supabase.storage.from('attachments').remove([storagePath]);
        } catch(e) { console.error("Failed to delete attachment from storage:", e) }
      }
    }
    const { error } = await supabase.from('transactions').delete().eq('id', id);
    if (error) {
        console.error("Error deleting transaction:", error.message);
        throw error;
    }
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  // Documents CRUD
  const addDocument = async (title: string, fileName: string, base64Data: string) => {
      const sanitizedName = fileName.replace(/[^a-zA-Z0-9.-]/g, '_');
      const storagePath = `documents/${crypto.randomUUID()}-${sanitizedName}`;

      const { error: uploadError } = await supabase.storage
          .from('attachments')
          .upload(storagePath, base64ToBlob(base64Data, 'image/jpeg'), {
            contentType: 'image/jpeg',
            upsert: true
          });

      if (uploadError) {
          console.error("Error uploading document:", uploadError.message);
          throw uploadError;
      }

      const newDocument = { title, file_name: fileName, storage_path: storagePath };
      const { data, error } = await supabase.from('documents').insert(newDocument).select();
      if (error) {
        console.error("Error saving document record:", error.message);
        await supabase.storage.from('attachments').remove([storagePath]);
        throw error;
      }
      if (data) setDocuments(prev => [data[0], ...prev]);
  };
  const deleteDocument = async (id: string) => {
      const docToDelete = documents.find(d => d.id === id);
      if (!docToDelete) return;

      const { error: storageError } = await supabase.storage.from('attachments').remove([docToDelete.storage_path]);
      if (storageError) console.error("Error deleting document from storage:", storageError.message);

      const { error: dbError } = await supabase.from('documents').delete().eq('id', id);
      if (dbError) return console.error("Error deleting document from DB:", dbError.message);

      setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const calculateCurrentBalance = useMemo(() => (accountId: string): number => {
    const account = accounts.find(acc => acc.id === accountId);
    if (!account) return 0;

    const accountTransactions = transactions.filter(t => t.accountId === accountId && t.type === 'checking_account');

    const balance = accountTransactions.reduce((acc, curr) => {
      if (curr.nature === 'RECEITA') {
        return acc + curr.value;
      }
      return acc - curr.value;
    }, 0);

    return balance;
  }, [accounts, transactions]);

  const contextValue = {
    isLoading,
    accounts, addAccount, updateAccount, deleteAccount, getAccountById,
    categories, addCategory, addCategoriesBatch, updateCategory, deleteCategory,
    transactions, addTransaction, addTransactionsBatch, updateTransaction, deleteTransaction,
    documents, addDocument, deleteDocument,
    keepAliveLogs,
    calculateCurrentBalance,
  };

  return (
    <AppContext.Provider value={contextValue}>
      {children}
    </AppContext.Provider>
  );
};

import React, { useState, useMemo } from 'react';
import { useAppData } from '../../hooks/useAppData';
import { Transaction, TransactionNature, CategoryType, NewAttachment, Attachment } from '../../types';
import Modal from '../ui/Modal';
import PdfOptionsModal from '../ui/PdfOptionsModal';
import CurrencyInput from '../ui/CurrencyInput';
import ViewAttachmentModal from '../ui/ViewAttachmentModal';
import { formatCurrency, formatDate } from '../../utils/formatters';
import { generateTransactionsPDF } from '../../utils/pdfGenerator';
import { 
  Plus, Trash2, FileText, Filter, Wallet, 
  Edit, MessageSquare, ChevronRight, X, CreditCard, Image as ImageIcon, Camera, Calendar, ArrowUpDown
} from 'lucide-react';

const TransactionForm: React.FC<{
  onSubmit: (transaction: Omit<Transaction, 'id'>, newAttachments: NewAttachment[]) => Promise<void>;
  onClose: () => void;
  transactionToEdit?: Transaction | null;
  transactionType: 'checking_account' | 'credit_card';
}> = ({ onSubmit, onClose, transactionToEdit, transactionType }) => {
    const { accounts, categories } = useAppData();
    const [nature, setNature] = useState<TransactionNature>(transactionToEdit?.nature || TransactionNature.DESPESA);
    const [description, setDescription] = useState(transactionToEdit?.description || '');
    const [accountId, setAccountId] = useState(transactionToEdit?.accountId || '');
    const [categoryId, setCategoryId] = useState(transactionToEdit?.categoryId || '');
    const [date, setDate] = useState(transactionToEdit?.date ? transactionToEdit.date.split('T')[0] : new Date().toISOString().split('T')[0]);
    const [value, setValue] = useState(transactionToEdit?.value || 0);
    const [comments, setComments] = useState(transactionToEdit?.comments || '');
    const [numeroNota, setNumeroNota] = useState(transactionToEdit?.numeroNota || '');
    const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'Cartão de Débito' | 'BOLETO' | undefined>(transactionToEdit?.paymentMethod);

    const [existingAttachments, setExistingAttachments] = useState<Attachment[]>(transactionToEdit?.attachments || []);
    const [newAttachments, setNewAttachments] = useState<NewAttachment[]>([]);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [viewingAttachment, setViewingAttachment] = useState<Attachment | null>(null);

    const filteredCategories = useMemo(() => {
        return categories.filter(c => c.type === (nature as unknown as CategoryType));
    }, [categories, nature]);

    const removeNewAttachment = (id: string) => {
        setNewAttachments(prev => prev.filter(a => a.id !== id));
    };

    const removeExistingAttachment = (id: string) => {
        setExistingAttachments(prev => prev.filter(a => a.id !== id));
    };

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                setNewAttachments(prev => [...prev, {
                    id: crypto.randomUUID(),
                    name: file.name,
                    data: base64,
                    type: 'image_base64_jpeg'
                }]);
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!accountId || !categoryId || value <= 0) return;

        setIsSubmitting(true);
        const transactionData = { 
            description, nature, accountId, categoryId, date, value, 
            type: transactionType, comments, numeroNota, 
            paymentMethod: transactionType === 'credit_card' ? undefined : paymentMethod,
            attachments: existingAttachments
        };
        await onSubmit(transactionData, newAttachments);
        setIsSubmitting(false);
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-8">
            <div className="space-y-4">
                <div className="flex items-center gap-2 mb-2">
                    <div className="bg-[#c5a059]/10 p-1.5 rounded-lg">
                        <Wallet size={14} className="text-[#c5a059]" />
                    </div>
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Informações Gerais</h4>
                </div>

                <div className="grid grid-cols-2 gap-3">
                    <button type="button" onClick={() => setNature(TransactionNature.RECEITA)} className={`p-3.5 rounded-xl font-bold uppercase tracking-widest text-[9px] transition-all active:scale-95 ${nature === TransactionNature.RECEITA ? 'bg-emerald-500 text-white shadow-lg' : 'bg-slate-100 text-slate-500'}`}>Crédito (+)</button>
                    <button type="button" onClick={() => setNature(TransactionNature.DESPESA)} className={`p-3.5 rounded-xl font-bold uppercase tracking-widest text-[9px] transition-all active:scale-95 ${nature === TransactionNature.DESPESA ? 'bg-rose-500 text-white shadow-lg' : 'bg-slate-100 text-slate-500'}`}>Débito (-)</button>
                </div>

                <div className="space-y-3">
                    <input type="text" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="O que foi pago/recebido?" className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none focus:ring-2 focus:ring-[#c5a059]" />
                    <CurrencyInput value={value} onChange={setValue} />
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <select value={accountId} onChange={(e) => setAccountId(e.target.value)} className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-semibold outline-none text-sm cursor-pointer">
                        <option value="">Selecione a Conta</option>
                        {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                    </select>

                    <select value={categoryId} onChange={(e) => setCategoryId(e.target.value)} className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-semibold outline-none text-sm cursor-pointer">
                        <option value="">Categoria</option>
                        {filteredCategories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                    </select>
                </div>

                <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none" />
            </div>

            <div className="space-y-4">
                <div className="flex items-center gap-2 mb-2">
                    <div className="bg-[#c5a059]/10 p-1.5 rounded-lg">
                        <CreditCard size={14} className="text-[#c5a059]" />
                    </div>
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Documentação</h4>
                </div>

                <div className={transactionType === 'credit_card' ? 'grid grid-cols-1' : 'grid grid-cols-1 sm:grid-cols-2 gap-3'}>
                    <input type="text" value={numeroNota} onChange={(e) => setNumeroNota(e.target.value)} placeholder="Nº da Nota / Cupom" className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none text-sm" />

                    {transactionType !== 'credit_card' && (
                        <select value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value as any)} className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-semibold outline-none text-sm cursor-pointer">
                            <option value="">Meio de Pagamento</option>
                            <option value="PIX">PIX</option>
                            <option value="Cartão de Débito">Cartão de Débito</option>
                            <option value="BOLETO">Boleto</option>
                        </select>
                    )}
                </div>

                <textarea 
                    value={comments} 
                    onChange={(e) => setComments(e.target.value)} 
                    placeholder="Observações importantes para prestação de contas..." 
                    rows={3}
                    className="w-full px-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none text-sm resize-none"
